WITH scored AS (SELECT id, city, opened_date, CUME_DIST() OVER (PARTITION BY region ORDER BY sqft DESC NULLS FIRST) AS sqft_cume_dist, NTILE(4) OVER (PARTITION BY region ORDER BY sqft DESC, id) AS sqft_bucket, ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date DESC, id) AS event_seq FROM stores), kept AS (SELECT s.* FROM scored s WHERE EXISTS (SELECT 1 FROM orders c WHERE c.store_id = s.id AND c.order_date <= s.opened_date)), with_windows AS (SELECT *, MIN(sqft_cume_dist) OVER w_recent AS last3_min_sqft_cume_dist, COUNT(sqft_cume_dist) OVER w_recent AS last3_count_sqft_cume_dist, SUM(sqft_cume_dist) OVER w_recent AS last3_sum_sqft_cume_dist, MAX(sqft_cume_dist) OVER w_recent AS last3_max_sqft_cume_dist, AVG(sqft_cume_dist) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS sqft_cume_dist_avg_5 FROM kept WINDOW w_recent AS (PARTITION BY city ORDER BY event_seq, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)), enriched AS (SELECT id, city, opened_date, sqft_cume_dist, last3_min_sqft_cume_dist, last3_count_sqft_cume_dist, last3_sum_sqft_cume_dist, PERCENT_RANK() OVER (PARTITION BY city ORDER BY last3_max_sqft_cume_dist DESC NULLS FIRST) AS last3_max_sqft_cume_dist_percent_rank, AVG(event_seq) OVER (PARTITION BY city ORDER BY last3_count_sqft_cume_dist, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS event_seq_avg_2, NTILE(10) OVER (ORDER BY sqft_cume_dist_avg_5 DESC, id) AS sqft_cume_dist_avg_5_bucket, ROW_NUMBER() OVER (PARTITION BY city ORDER BY sqft_cume_dist_avg_5 DESC, id) AS row_seq, AVG(sqft_bucket) OVER (PARTITION BY city ORDER BY last3_max_sqft_cume_dist, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS sqft_bucket_avg_2_prior FROM with_windows WHERE city NOT IN ('Chiang Mai', 'London')) SELECT city, APPROX_PERCENTILE(row_seq, ARRAY(0.25, 0.5, 0.75)) AS row_seq_quartiles, MAX(event_seq_avg_2) FILTER (WHERE city = 'Berlin') AS berlin_max_event_seq_avg_2 FROM enriched GROUP BY city
